        {{#if banners.top}}
            {{#each banners.top_metadata}}
                {{#unless (occurrences this.content 'halo_top2_banners') '>' 0}}
                {{#unless (occurrences this.content 'halo_top_brands') '>' 0}}
                {{#unless (occurrences this.content 'halo_top_banners') '>' 0}}
