                {{#unless (occurrences this.content 'halo_middle_banners') '>' 0}}
                {{#unless (occurrences this.content 'halo_middle_parralax_banners') '>' 0}}
                {{#unless (occurrences this.content 'halo_parralax_banners') '>' 0}}
                {{#unless (occurrences this.content 'halo_bottom_banners') '>' 0}}
